// Non-English site dictionaries.
//
// This file is imported LAZILY — only when a visitor actually picks a language
// (see src/i18n.jsx). English is the default and stays in the first-load
// bundle; shipping thirteen dictionaries to every visitor who will never use
// them cost ~13 kB gzipped on first load, which is exactly the wrong trade.
//
// To add a language: add it to LANGUAGES in src/i18n.js, add its dictionary
// here, and run `npm run test:i18n` — the test fails if a language is
// advertised but has no dictionary.

// ---------------------------------------------------------------------------
// Translations. Each dictionary only carries what it can carry honestly: the
// machinery desk and the contact path, which is where non-English buyers land.
// Screens that are not translated fall back to English rather than to a
// half-translated page.
// ---------------------------------------------------------------------------
