  'about.h2': 'بُنينا لنكون شريكك الموثوق.',
  'about.body': 'تربط AR7 Traders المشترين حول العالم بعمق وجودة سوق السيارات الياباني.',
  'about.story': 'يورّد فريقنا عبر كبرى دور المزادات اليابانية وشبكات وكلاء موثوقة. تُختار كل سيارة بفحص دقيق وتواصل واضح وشفافية كاملة في التكاليف.',
  'faq.kicker': 'الأسئلة الشائعة',
  'faq.h2': 'الشراء من اليابان، بوضوح.',
  'faq.body': 'إجابات عملية عن المزادات اليابانية ومخزون الوكلاء والتسعير والشحن والتخليص في الميناء — مرتبة حسب الموضوع.',
  'faq.ask': 'اطرح سؤالاً آخر',
  'faq.topicAuctions': 'المزادات والحالة',
  'faq.topicPricing': 'التسعير والدفع',
  'faq.topicShipping': 'الشحن والمستندات',
  'faq.topicArrival': 'الجمارك والوصول',
  'faq.q1': 'كيف تعمل مزادات السيارات اليابانية؟',
  'faq.a1': 'يقوم أعضاء تجاريون مرخصون بفحص السيارات والمزايدة عليها في دور مزادات الجملة في أنحاء اليابان. تقوم AR7 بترشيح اللوتات المناسبة وترجمة ملاحظات الفاحص ووضع حدك الأقصى المتفق عليه نيابة عنك.',
  'faq.q2': 'هل يمكنني رؤية تقرير المزاد قبل المزايدة؟',
  'faq.a2': 'للسيارات القادمة من المزاد، نعم — نشاركك تقرير المزاد الياباني وملخصاً واضحاً للدرجات والعلامات قبل التزامك بالمزايدة. أما سيارات مخزون الوكلاء فتُراجع حالتها من تقرير الوكيل وصور الساحة.',
  'faq.q3': 'ماذا تعني درجات المزاد اليابانية مثل 4.5 و4.0 وR؟',
  'faq.a3': 'تشير الدرجات S و5 و4.5 و4.0 إلى الحالة العامة وفئة الممشى، بينما ترمز أكواد الألواح مثل A1 (خدش صغير) وU1 (انبعاج بسيط) وW2 (تموج طلاء) إلى حالة كل لوح. درجة R أو RA تعني تاريخ حادث مُصلح — ونوضح ذلك بجلاء قبل قرارك.',
  'faq.q4': 'ما الفرق بين مخزون الوكلاء وسيارة المزاد؟',
  'faq.a4': 'تُباع سيارات المزاد في يوم مزايدة محدد بسعر مطرقة بالين الياباني، بينما سيارات مخزون الوكلاء مسعّرة بالفعل لدى الوكالات اليابانية ويمكن حجزها فوراً دون انتظار جلسة مزاد.',
  'faq.q5': 'هل تستطيع AR7 توريد موديل محدد؟',
  'faq.a5': 'نعم. شاركنا الماركة والموديل ونطاق السنة وسقف الممشى واللون المفضل وميناء الوجهة. نراقب قوائم المزادات اليومية وشبكات الوكلاء اليابانية حتى تظهر سيارة مطابقة.',
  'faq.q6': 'ماذا يشمل سعر التصدير؟',
  'faq.a6': 'سعر السيارة المعلن هو تقدير مبدئي FOB (تسليم ظهر السفينة) في اليابان. يفصّل عرض السعر المكتوب سعر السيارة والنقل الداخلي الياباني وتجهيز التصدير والشحن البحري وتأمين النقل البحري (CIF).',
  'faq.q7': 'ما الفرق بين تسعير FOB وCIF؟',
  'faq.a7': 'يغطي FOB السيارة وتجهيز التصدير حتى التحميل في الميناء الياباني. يضيف CIF (التكلفة والتأمين والشحن) الشحن البحري إلى ميناء وجهتك وتأمين النقل البحري لترى تكلفة الوصول للميناء قبل الجمارك.',
  'faq.q8': 'كيف أدفع ثمن السيارة وما العملات المقبولة؟',
  'faq.a8': 'تُسوى المشتريات بتحويل مصرفي دولي (T/T) مقابل فاتورة مبدئية مفصلة، عادة بالدولار الأمريكي أو الين الياباني. للمزايدة في المزاد، وديعة قابلة للاسترداد تفعّل حد مزايدتك ويُفوتر الرصيد بعد الشراء الناجح.',
  'faq.q9': 'هل أرقام الحاسبات على الموقع عروض نهائية؟',
  'faq.a9': 'لا — جميع نتائج الحاسبات ونوافذ العبور على الموقع تقديرات للتخطيط. قبل التزامك، يصدر مكتب التصدير الياباني لدينا عرض سعر مكتوباً بتكاليف الشحن والتوثيق الحالية لسيارتك بالتحديد.',
  'faq.q10': 'كم يستغرق الشحن؟',
  'faq.a10': 'يعتمد العبور البحري على ميناء وجهتك وجدول الناقل وما إذا كانت السفينة مباشرة أو بمسافنة. تتراوح نوافذ التخطيط المعتادة من نحو 18 إلى 42 يوماً بعد التحميل في اليابان.',
  'faq.q11': 'هل أختار شحن RoRo أم الحاويات؟',
  'faq.a11': 'RoRo (الدحرجة) هو الخيار القياسي الاقتصادي للسيارات القابلة للقيادة ومركبات الدفع الرباعي والفانات. أما الحاويات المخصصة أو المشتركة فتناسب السيارات الخارقة عالية القيمة أو المنخفضة أو طلبات الوكالات متعددة السيارات.',
  'faq.q12': 'ما مستندات التصدير التي سأستلمها؟',
  'faq.a12': 'تُجهز كل شحنة بفاتورة تجارية وبوليصة شحن أصلية وشهادة تصدير يابانية (شهادة إلغاء التسجيل) وشهادة تأمين بحري، إضافة إلى شهادات فحص ما قبل الشحن (مثل QISJ أو JEVIC أو EAA) حيثما يتطلب سوقك.',
  'faq.q13': 'كيف أتتبع سيارتي؟',
  'faq.a13': 'يتلقى العملاء تحديثات عبر البوابة وواتساب تشمل صور وصول الساحة في اليابان وفحص ما قبل التصدير وحجز السفينة وإرسال بوليصة الشحن بالبريد السريع وموعد الوصول المقدر للميناء.',
  'faq.q14': 'من يحسب رسوم الاستيراد ويخلّص السيارة في مينائي؟',
  'faq.a14': 'تُقدَّر رسوم الاستيراد والضرائب المحلية ورسوم التسجيل دائماً من سلطة الجمارك في بلدك وفق القواعد المحلية. يقدم وكيل التخليص المرخص لديك في ميناء الوجهة المستندات الأصلية التي نرسلها إليك ويؤكد الرسوم المستحقة بدقة.',

