  'about.h2': 'جوړ شوي چې ستاسو باوري شریک واوسو.',
  'about.body': 'AR7 Traders نړیوال پیرودونکي د جاپاني موټرو بازار له ژوروالي او کیفیت سره نښلوي.',
  'about.story': 'زموږ ټیم د جاپان له لویو لیلام خونو او باوري د پلورونکو شبکو له لارې توريد کوي. هر موټر په دقیقه معاینه، روښانه اړیکه او د لګښتونو بشپړه روڼتیا غوره کیږي.',
  'faq.kicker': 'مشهورې پوښتنې',
  'faq.h2': 'له جاپانه پیرود، تشریح شوی.',
  'faq.body': 'د جاپاني لیلامونو، د پلورونکو سټاک، بیو، بار وړنې او په بندر کې ترخیص په اړه عملي ځوابونه — د موضوع له مخې ګروپ شوي.',
  'faq.ask': 'بله پوښتنه وکړئ',
  'faq.topicAuctions': 'لیلامونه او حالت',
  'faq.topicPricing': 'بیې او تادیه',
  'faq.topicShipping': 'بار وړنه او اسناد',
  'faq.topicArrival': 'ګمرک او رارسیدل',
  'faq.q1': 'جاپاني د موټرو لیلامونه څنګه کار کوي؟',
  'faq.a1': 'جواز لرونکي سوداګر غړي په ټول جاپان کې د عمده لیلام خونو کې موټرونه معاینه کوي او بولۍ پرې وهي. AR7 مناسب لوټونه لنډلیست کوي، د معاینه کوونکي یادښتونه ژباړي او ستاسو هوکړه شوې اعظمي بولۍ ستاسو پر ځای ږدي.',
  'faq.q2': 'ایا له بولۍ مخکې د لیلام شیټ لیدلی شم؟',
  'faq.a2': 'د لیلام لوټونو لپاره، هو — له ژمنتیا مخکې جاپاني د لیلام شیټ او د درجو او نښو ساده لنډیز درسره شریکوو. د پلورونکي سټاک موټرو حالت د پلورونکي له راپور او د انګړ له عکسونو کتل کیږي.',
  'faq.q3': 'جاپاني د لیلام درجې لکه 4.5، 4.0 او R څه مانا لري؟',
  'faq.a3': 'درجې S، 5، 4.5 او 4.0 ټولیز حالت او د کیلومترۍ کچه ښيي، او د پاڼل کوډونه لکه A1 (کوچنی خراش)، U1 (وړوکی ټک) او W2 (د رنګ څپه) جلا پاڼلونه نښه کوي. د R یا RA درجه د ترمیم شوي حادثې تاریخ مانا لري — له پریکړې مخکې یې په ډاګه کوو.',
  'faq.q4': 'د پلورونکي سټاک له لیلام موټره څنګه توپیر لري؟',
  'faq.a4': 'د لیلام موټرونه په ټاکلې ورځ د جاپاني ین په قیمت پلورل کیږي، خو د پلورونکي سټاک موټرونه له وړاندې په جاپاني پلورنځیو کې قیمت لري او پرته له لیلامه سمدستي ریزرو کیدی شي.',
  'faq.q5': 'ایا AR7 ځانګړی ماډل توریدولی شي؟',
  'faq.a5': 'هو. خپل برانډ، ماډل، د کال حدود، د کیلومترۍ سقف، غوره رنګ او د منزل بندر شریک کړئ. موږ ورځني د لیلام لیستونه او جاپاني د پلورونکو شبکې څارو تر هغه چې سمون لرونکی موټر پیدا شي.',
  'faq.q6': 'په صادراتي بیه کې څه شامل دي؟',
  'faq.a6': 'اعلان شوې بیه په جاپان کې د FOB (پر کښتۍ سپارل) پیل اټکل دی. ستاسو لیکلی وړاندیز د موټر بیه، جاپاني داخلي ترانسپورت او د صادراتو چمتووالی، سمندري کرایه او سمندري بیمه (CIF) په تفصیل ښيي.',
  'faq.q7': 'د FOB او CIF بیو کې څه توپیر دی؟',
  'faq.a7': 'FOB موټر او د صادراتو چمتووالی په جاپاني بندر کې تر بارولو پورې پوښي. CIF (لګښت، بیمه او کرایه) ستاسو د منزل بندر ته سمندري کرایه او سمندري بیمه ورزیاتوي ترڅو له ګمرک مخکې د بندر ته د رسیدو لګښت وګورئ.',
  'faq.q8': 'د موټر پیسې څنګه ورکوم او کومې اسعارې منل کیږي؟',
  'faq.a8': 'پیرودنې د تفصيلي پروفورما انووس پر وړاندې په نړیوال بانکي انتقال (T/T) تصفیه کیږي، معمولاً په USD یا JPY. د لیلام بولۍ لپاره، بیرته ورکړې وړ ودیعه ستاسو د بولۍ حد فعالوي او پاتې پیسې له بریالي پیرود وروسته انووس کیږي.',
  'faq.q9': 'ایا د ویب پاڼې د محاسبو شمیرې وروستي وړاندیزونه دي؟',
  'faq.a9': 'نه — په ویب پاڼه کې ټولې د محاسبې پایلې او د لېږد مودې د پلان اټکلونه دي. له ژمنتیا مخکې، زموږ د جاپان د صادراتو میز ستاسو د ځانګړي موټر لپاره د اوسنیو کرایو او اسنادو له لګښتونو سره لیکلی وړاندیز صادروي.',
  'faq.q10': 'بار وړنه څومره وخت نیسي؟',
  'faq.a10': 'سمندري لېږد ستاسو د منزل په بندر، د شرکت په مهالویش او دا پورې اړه لري چې کښتۍ مستقیمه ځي که بدلیږي. معمولي د پلان مودې په جاپان کې له بارولو وروسته شاوخوا له 18 تر 42 ورځو وي.',
  'faq.q11': 'RoRo غوره کړم که کانټینري بار وړنه؟',
  'faq.a11': 'RoRo د چلیدونکو موټرو، SUV او وینونو لپاره معیاري او اقتصادي انتخاب دی. ځانګړي یا شریک کانټینرونه د لوړ ارزښت سوپرکارونو، ټیټو موټرو یا د پلورنځیو ډله ییزو فرمایشونو لپاره مناسب دي.',
  'faq.q12': 'کوم د صادراتو اسناد به ترلاسه کړم؟',
  'faq.a12': 'هر بارګنډ د سوداګریز انووس، اصلي بل آف لېډینګ، جاپاني د صادراتو سند (د راجسترېشن د لغوه کولو سند) او د سمندري بیمې سند سره چمتو کیږي، او چیرې چې ستاسو بازار یې غواړي د بار وړنې دمخه معاینې سندونه (لکه QISJ، JEVIC یا EAA) هم.',
  'faq.q13': 'خپل موټر څنګه تعقیب کړم؟',
  'faq.a13': 'پیرودونکي د پورټال او واټساپ تازه معلومات ترلاسه کوي چې په جاپان کې انګړ ته د رسیدو عکسونه، له صادراتو مخکې معاینه، د کښتۍ بکینګ، په کوریر د بل آف لېډینګ لیږل او بندر ته اټکلي رسیدل پوښي.',
  'faq.q14': 'د واردولو محصول څوک حسابوي او زما په بندر کې موټر څوک ترخیصوي؟',
  'faq.a14': 'د واردولو محصول، محلي مالیات او د راجسترېشن فیسونه تل ستاسو د هیواد د ګمرک له خوا د محلي قواعدو له مخې ټاکل کیږي. ستاسو جواز لرونکی ترخیص اجنټ په منزل بندر کې هغه اصلي اسناد وړاندې کوي چې موږ یې درلیږو او دقیق محصول تاییدوي.',

