  'faq.a1': 'لائسنس یافتہ تجارتی ممبر جاپان بھر کے ہول سیل نیلام گھروں میں گاڑیوں کا معائنہ اور بولی لگاتے ہیں۔ AR7 موزوں لاٹس شارٹ لسٹ کرتا ہے، انسپکٹر نوٹس کا ترجمہ کرتا ہے اور آپ کی طے شدہ زیادہ سے زیادہ بولی آپ کی طرف سے لگاتا ہے۔',
  'faq.q2': 'کیا بولی سے پہلے نیلامی شیٹ دیکھ سکتا ہوں؟',
  'faq.a2': 'نیلامی سے حاصل لاٹس کے لیے، جی ہاں — بولی کے عہد سے پہلے ہم جاپانی نیلامی شیٹ اور گریڈز و نشانات کا سادہ خلاصہ شیئر کرتے ہیں۔ ڈیلر اسٹاک گاڑیوں کی حالت ڈیلر رپورٹ اور یارڈ تصاویر سے جانچی جاتی ہے۔',
  'faq.q3': 'جاپانی نیلامی گریڈز جیسے 4.5، 4.0 اور R کا کیا مطلب ہے؟',
  'faq.a3': 'گریڈز S، 5، 4.5 اور 4.0 مجموعی حالت اور مائلیج بینڈ ظاہر کرتے ہیں، جبکہ پینل کوڈز جیسے A1 (چھوٹی خراش)، U1 (معمولی ڈینٹ) اور W2 (پینٹ ویو) انفرادی پینلز کی نشاندہی کرتے ہیں۔ R یا RA گریڈ مرمت شدہ حادثے کی تاریخ ہے — فیصلے سے پہلے ہم اسے واضح کرتے ہیں۔',
  'faq.q4': 'ڈیلر اسٹاک نیلامی گاڑی سے کیسے مختلف ہے؟',
  'faq.a4': 'نیلامی گاڑیاں مقررہ بولی کے دن جاپانی ین میں ہیمر پرائس پر فروخت ہوتی ہیں، جبکہ ڈیلر اسٹاک گاڑیاں جاپانی ڈیلرشپس پر پہلے سے قیمت شدہ ہیں اور نیلامی سیشن کا انتظار کیے بغیر فوری ریزرو ہو سکتی ہیں۔',
  'faq.q5': 'کیا AR7 کوئی مخصوص ماڈل سورس کر سکتا ہے؟',
  'faq.a5': 'جی ہاں۔ اپنا مطلوبہ برانڈ، ماڈل، سال کی حد، مائلیج کیپ، پسندیدہ رنگ اور منزل کی بندرگاہ بتائیں۔ ہم روزانہ نیلامی فہرستیں اور جاپانی ڈیلر نیٹ ورکس اس وقت تک مانیٹر کرتے ہیں جب تک مطابق گاڑی نہ مل جائے۔',
  'faq.q6': 'ایکسپورٹ قیمت میں کیا شامل ہے؟',
  'faq.a6': 'درج گاڑی کی قیمت جاپان میں FOB (فری آن بورڈ) ابتدائی تخمینہ ہے۔ آپ کا تحریری کوٹیشن گاڑی کی قیمت، جاپانی اندرونِ ملک ٹرانسپورٹ اور ایکسپورٹ تیاری، سمندری فریٹ اور میرین ٹرانزٹ انشورنس (CIF) کی تفصیل دیتا ہے۔',
  'faq.q7': 'FOB اور CIF قیمتوں میں کیا فرق ہے؟',
  'faq.a7': 'FOB جاپانی بندرگاہ پر لوڈنگ تک گاڑی اور ایکسپورٹ تیاری کور کرتا ہے۔ CIF (کاسٹ، انشورنس اینڈ فریٹ) آپ کی منزل کی بندرگاہ تک سمندری فریٹ اور میرین انشورنس شامل کرتا ہے تاکہ کسٹمز سے پہلے بندرگاہ تک کی لاگت نظر آئے۔',
  'faq.q8': 'گاڑی کی ادائیگی کیسے کروں اور کون سی کرنسیاں قبول ہیں؟',
  'faq.a8': 'خریداری تفصیلی پروفارما انوائس کے بدلے بین الاقوامی بینک ٹرانسفر (T/T) سے طے ہوتی ہے، عموماً USD یا JPY میں۔ نیلامی بولی کے لیے قابلِ واپسی ڈپازٹ آپ کی بولی کی حد فعال کرتا ہے اور بقیہ کامیاب خریداری کے بعد انوائس ہوتا ہے۔',
  'faq.q9': 'کیا ویب سائٹ کے کیلکولیٹر نمبرز حتمی کوٹس ہیں؟',
  'faq.a9': 'نہیں — ویب سائٹ کے تمام کیلکولیٹر نتائج اور ترسیل کے دورانیے پلاننگ تخمینے ہیں۔ عہد سے پہلے ہمارا جاپان ایکسپورٹ ڈیسک آپ کی مخصوص گاڑی کے لیے موجودہ کیریئر فریٹ اور دستاویزی لاگت کے ساتھ تحریری کوٹیشن جاری کرتا ہے۔',
  'faq.q10': 'شپنگ میں کتنا وقت لگتا ہے؟',
  'faq.a10': 'سمندری ترسیل آپ کی منزل کی بندرگاہ، کیریئر شیڈول اور جہاز کے براہِ راست یا ٹرانس شپ ہونے پر منحصر ہے۔ عام پلاننگ دورانیے جاپان میں لوڈنگ کے بعد تقریباً 18 سے 42 دن ہوتے ہیں۔',
  'faq.q11': 'RoRo چنوں یا کنٹینر شپنگ؟',
  'faq.a11': 'RoRo (رول آن/رول آف) چلنے والی کاروں، SUVs اور وینز کے لیے معیاری، کم لاگت انتخاب ہے۔ مخصوص یا مشترکہ کنٹینرز قیمتی سپر کاروں، کم کلیئرنس گاڑیوں یا ملٹی کار ڈیلرشپ آرڈرز کے لیے موزوں ہیں۔',
  'faq.q12': 'مجھے کون سی ایکسپورٹ دستاویزات ملیں گی؟',
  'faq.a12': 'ہر شپمنٹ کمرشل انوائس، اصل بل آف لیڈنگ، جاپانی ایکسپورٹ سرٹیفکیٹ (ڈی رجسٹریشن سرٹیفکیٹ) اور میرین انشورنس سرٹیفکیٹ کے ساتھ تیار ہوتی ہے، نیز جہاں آپ کی مارکیٹ کو درکار ہو پری شپمنٹ انسپیکشن سرٹیفکیٹس (جیسے QISJ، JEVIC یا EAA)۔',
  'faq.q13': 'میں اپنی گاڑی کیسے ٹریک کروں؟',
  'faq.a13': 'کلائنٹس کو پورٹل اور واٹس ایپ اپڈیٹس ملتی ہیں جن میں جاپان میں یارڈ آمد کی تصاویر، پری ایکسپورٹ معائنہ، ویسل بکنگ، کورئیر سے بل آف لیڈنگ کی روانگی اور بندرگاہ آمد کا تخمینہ شامل ہے۔',
  'faq.q14': 'امپورٹ ڈیوٹی کون لگاتا ہے اور میری بندرگاہ پر گاڑی کون کلیئر کرتا ہے؟',
  'faq.a14': 'امپورٹ ڈیوٹی، مقامی ٹیکس اور رجسٹریشن فیس ہمیشہ آپ کے اپنے ملک کی کسٹمز اتھارٹی مقامی قوانین کے تحت طے کرتی ہے۔ منزل کی بندرگاہ پر آپ کا لائسنس یافتہ کلیئرنگ ایجنٹ ہماری کورئیر کردہ اصل دستاویزات جمع کرا کے عین واجب الادا ڈیوٹی کی تصدیق کرتا ہے۔',

