  'page.getStarted': 'شروع کنید',
  'page.sendEnquiry': 'ارسال درخواست',
  'about.h2': 'ساخته شده تا شریک مطمئن شما باشیم.',
  'about.body': 'AR7 Traders خریداران سراسر جهان را به عمق و کیفیت بازار خودروی ژاپن متصل می‌کند.',
  'about.story': 'تیم ما از بزرگ‌ترین خانه‌های مزایده ژاپن و شبکه‌های معتبر نمایندگی تأمین می‌کند. هر خودرو با بازرسی دقیق، ارتباط روشن و شفافیت کامل هزینه‌ها انتخاب می‌شود.',
  'faq.kicker': 'پرسش‌های پرتکرار',
  'faq.h2': 'خرید از ژاپن، به‌روشنی.',
  'faq.body': 'پاسخ‌های عملی درباره مزایده‌های ژاپن، موجودی نمایندگی، قیمت، حمل و ترخیص بندر — دسته‌بندی‌شده بر اساس موضوع.',
  'faq.ask': 'پرسش دیگری بپرسید',
  'faq.topicAuctions': 'مزایده و وضعیت',
  'faq.topicPricing': 'قیمت و پرداخت',
  'faq.topicShipping': 'حمل و اسناد',
  'faq.topicArrival': 'گمرک و رسیدن',
  'faq.q1': 'مزایده‌های خودرو در ژاپن چگونه کار می‌کنند؟',
  'faq.a1': 'اعضای تجاری دارای مجوز در خانه‌های مزایده عمده‌فروشی سراسر ژاپن خودروها را بازرسی و روی آنها پیشنهاد می‌دهند. AR7 لات‌های مناسب را فهرست می‌کند، یادداشت بازرس را ترجمه و سقف توافق‌شده شما را از طرف شما ثبت می‌کند.',
  'faq.q2': 'آیا می‌توانم برگه مزایده را پیش از پیشنهاد ببینم؟',
  'faq.a2': 'برای لات‌های مزایده، بله — پیش از تعهد به پیشنهاد، برگه مزایده ژاپنی و خلاصه‌ای ساده از نمره‌ها و علامت‌ها را با شما به اشتراک می‌گذاریم. وضعیت خودروهای موجودی نمایندگی از گزارش نمایندگی و عکس‌های محوطه بررسی می‌شود.',
  'faq.q3': 'نمره‌های مزایده ژاپن مثل 4.5، 4.0 و R یعنی چه؟',
  'faq.a3': 'نمره‌های S، 5، 4.5 و 4.0 وضعیت کلی و رده کارکرد را نشان می‌دهند و کدهای بدنه مثل A1 (خراش کوچک)، U1 (قر جزئی) و W2 (موج رنگ) تک‌تک پنل‌ها را مشخص می‌کنند. نمره R یا RA یعنی سابقه تصادف تعمیرشده — پیش از تصمیم شما آن را به‌روشنی اعلام می‌کنیم.',
  'faq.q4': 'موجودی نمایندگی با خودروی مزایده چه فرقی دارد؟',
  'faq.a4': 'خودروهای مزایده در روز مشخص با قیمت چکش به ین ژاپن فروخته می‌شوند، اما خودروهای موجودی نمایندگی از قبل در نمایندگی‌های ژاپن قیمت‌گذاری شده‌اند و بدون انتظار برای جلسه مزایده فوراً قابل رزروند.',
  'faq.q5': 'آیا AR7 می‌تواند مدل مشخصی تأمین کند؟',
  'faq.a5': 'بله. برند، مدل، بازه سال، سقف کارکرد، رنگ دلخواه و بندر مقصد را بگویید. فهرست‌های روزانه مزایده و شبکه‌های نمایندگی ژاپن را رصد می‌کنیم تا خودروی منطبق پیدا شود.',
  'faq.q6': 'قیمت صادراتی شامل چه چیزهایی است؟',
  'faq.a6': 'قیمت درج‌شده، تخمین آغازین FOB (تحویل روی عرشه) در ژاپن است. پیش‌فاکتور مکتوب شما قیمت خودرو، حمل داخلی ژاپن و آماده‌سازی صادرات، کرایه دریایی و بیمه حمل دریایی (CIF) را جزءبه‌جزء نشان می‌دهد.',
  'faq.q7': 'تفاوت قیمت FOB و CIF چیست؟',
  'faq.a7': 'FOB خودرو و آماده‌سازی صادرات را تا بارگیری در بندر ژاپن پوشش می‌دهد. CIF (هزینه، بیمه و کرایه) کرایه دریایی تا بندر مقصد و بیمه حمل دریایی را اضافه می‌کند تا هزینه رسیدن به بندر را پیش از گمرک ببینید.',
  'faq.q8': 'چطور هزینه خودرو را بپردازم و چه ارزهایی پذیرفته می‌شود؟',
  'faq.a8': 'خریدها با حواله بانکی بین‌المللی (T/T) در برابر پیش‌فاکتور جزءبه‌جزء تسویه می‌شوند، معمولاً به USD یا JPY. برای پیشنهاد در مزایده، ودیعه قابل‌استرداد سقف پیشنهاد شما را فعال می‌کند و مانده پس از خرید موفق فاکتور می‌شود.',
  'faq.q9': 'آیا اعداد ماشین‌حساب سایت پیشنهاد نهایی‌اند؟',
  'faq.a9': 'خیر — همه خروجی‌های ماشین‌حساب و بازه‌های حمل سایت تخمین برنامه‌ریزی‌اند. پیش از تعهد، میز صادرات ژاپن ما پیش‌فاکتور مکتوبی با کرایه فعلی کریر و هزینه اسناد برای خودروی مشخص شما صادر می‌کند.',
  'faq.q10': 'حمل چقدر طول می‌کشد؟',
  'faq.a10': 'ترانزیت دریایی به بندر مقصد، برنامه کریر و مستقیم یا ترانشیپ بودن کشتی بستگی دارد. بازه معمول برنامه‌ریزی حدود ۱۸ تا ۴۲ روز پس از بارگیری در ژاپن است.',
  'faq.q11': 'RoRo انتخاب کنم یا حمل کانتینری؟',
  'faq.a11': 'RoRo (سوار و پیاده‌شدنی) انتخاب استاندارد و مقرون‌به‌صرفه برای خودروهای قابل‌رانندگی، شاسی‌بلندها و ون‌هاست. کانتینر اختصاصی یا اشتراکی مناسب سوپرکارهای گران‌قیمت، خودروهای کم‌ارتفاع یا سفارش‌های چندخودرویی نمایندگی‌هاست.',
  'faq.q12': 'کدام اسناد صادرات را دریافت می‌کنم؟',
  'faq.a12': 'هر محموله با فاکتور تجاری، بارنامه اصلی، گواهی صادرات ژاپن (گواهی ابطال پلاک) و گواهی بیمه دریایی آماده می‌شود، به‌علاوه گواهی‌های بازرسی پیش از حمل (مانند QISJ، JEVIC یا EAA) هر جا بازار شما لازم داشته باشد.',
  'faq.q13': 'خودرویم را چگونه پیگیری کنم؟',
  'faq.a13': 'مشتریان از پرتال و واتس‌اپ به‌روزرسانی می‌گیرند: عکس رسیدن به محوطه در ژاپن، بازرسی پیش از صادرات، رزرو کشتی، ارسال بارنامه با پیک و زمان تخمینی رسیدن به بندر.',
  'faq.q14': 'عوارض واردات را چه کسی حساب می‌کند و خودرو را در بندر من چه کسی ترخیص می‌کند؟',
  'faq.a14': 'عوارض واردات، مالیات محلی و هزینه‌های ثبت همیشه توسط گمرک کشور شما طبق قواعد محلی تعیین می‌شود. ترخیص‌کار مجاز شما در بندر مقصد اسناد اصلی را که برایتان می‌فرستیم ارائه و عوارض دقیق را تأیید می‌کند.',

