  'hb.s2w': 'برای لات‌های حراج، کارشناس مستقر در ژاپن یادداشت‌های دست‌نویس بازرس، درجه پانل‌ها و علائم داخلی را به زبان ساده ترجمه می‌کند؛ برای موجودی نمایندگی، یادداشت‌های وضعیت و مجموعه عکس نمایندگی را به اشتراک می‌گذاریم.',
  'hb.s3t': 'سقف پیشنهاد را تعیین کنید',
  'hb.s3p': 'پیش از شرکت در حراج، سقف قطعی توافق می‌شود — بدون شگفتی، بدون افزایش.',
  'hb.s3w': 'شما حداکثر پیشنهاد کتبی را به JPY یا USD همراه با برآورد تفکیکی CIF تأیید می‌کنید و ما آن سقف را پیش از ورود لات به خط حراج قفل می‌کنیم.',
  'hb.s4t': 'ما برای شما پیشنهاد می‌دهیم',
  'hb.s4p': 'نمایندگان ما به‌صورت زنده در USS، TAA، JU، CAA و دیگر حراجی‌ها پیشنهاد می‌دهند؛ شما در پورتال دنبال می‌کنید.',
  'hb.s4w': 'میز حراج ما تا سقف توافق‌شده پیشنهادهای زنده سالنی یا ترمینالی ثبت می‌کند و نتیجه چکش را بلافاصله پس از بسته‌شدن لات اعلام می‌کند.',
  'hb.s5t': 'بازرسی و آماده‌سازی',
  'hb.s5p': 'عکس‌های مستقل محوطه، بررسی زیر بدنه، تطبیق وضعیت با برگه حراج یا گزارش نمایندگی و آماده‌سازی پیش از صادرات.',
  'hb.s5w': 'وقتی خودرو به محوطه صادراتی ما در ژاپن می‌رسد، از بیرون، داخل و زیر بدنه عکس می‌گیریم، هر بازرسی اجباری پیش از حمل (مانند QISJ، JEVIC یا پاک‌سازی قرنطینه‌ای) را انجام می‌دهیم و آن را برای بارگیری آماده می‌کنیم.',
  'hb.s6t': 'مرحله‌ای پرداخت کنید',
  'hb.s6p': 'ودیعه، حراج را فعال می‌کند؛ مانده طبق فاکتور شما پیش و پس از حمل تقسیم می‌شود.',
  'hb.s6w': 'پیش‌فاکتور جزءبه‌جزء دریافت می‌کنید که قیمت خودرو، آماده‌سازی صادرات، کرایه و بیمه دریایی را نشان می‌دهد؛ تسویه با حواله بانکی (T/T) انجام می‌شود و هر پرداخت در پورتال شما ثبت می‌گردد.',
