  'page.aboutKicker': 'À PROPOS D\'AR7 TRADERS',
  'page.aboutH1a': 'Votre équipe',
  'page.aboutH1b': 'sur le terrain',
  'page.aboutH1em': 'au Japon.',
  'page.aboutBody': 'Nous sommes des spécialistes du sourcing automobile, fondés sur la transparence, la qualité et des relations clients durables.',
  'page.contactKicker': 'PARLEZ À NOTRE ÉQUIPE',
  'page.contactH1a': 'Commencez votre',
  'page.contactH1em': 'aventure auto.',
  'page.contactBody': 'Dites-nous votre marché, votre budget et le véhicule souhaité. Notre bureau export au Japon répondra avec des options adaptées.',
  'page.getStarted': 'Commencer',
  'page.sendEnquiry': 'Envoyer une demande',
  'about.h2': 'Conçus pour être votre partenaire de confiance.',
  'about.body': 'AR7 Traders relie les acheteurs du monde entier à la profondeur et à la qualité du marché automobile japonais.',
  'about.story': 'Notre équipe s\'approvisionne auprès des grandes maisons d\'enchères japonaises et de réseaux de concessionnaires fiables. Chaque véhicule est choisi avec une inspection rigoureuse, une communication claire et une transparence totale des coûts.',
  'faq.kicker': 'QUESTIONS FRÉQUENTES',
  'faq.h2': 'Acheter au Japon, expliqué.',
  'faq.body': 'Des réponses pratiques sur les enchères japonaises, le stock concessionnaire, les prix, l\'expédition et le dédouanement — classées par thème.',
  'faq.ask': 'Poser une autre question',
  'faq.topicAuctions': 'Enchères & état',
  'faq.topicPricing': 'Prix & paiement',
  'faq.topicShipping': 'Expédition & documents',
  'faq.topicArrival': 'Douane & arrivée',
  'faq.q1': 'Comment fonctionnent les enchères automobiles japonaises ?',
  'faq.a1': 'Des membres professionnels agréés inspectent et enchérissent sur les véhicules dans les maisons d\'enchères de gros du Japon. AR7 présélectionne les lots adaptés, traduit les notes de l\'inspecteur et place votre enchère maximale convenue en votre nom.',
  'faq.q2': 'Puis-je voir la fiche d\'enchère avant d\'enchérir ?',
  'faq.a2': 'Pour les lots d\'enchères, oui — nous partageons la fiche japonaise et un résumé clair des notes et marques avant tout engagement. Pour le stock concessionnaire, l\'état est évalué d\'après le rapport du vendeur et les photos du parc.',
  'faq.q3': 'Que signifient les notes d\'enchères comme 4.5, 4.0 et R ?',
  'faq.a3': 'Les notes S, 5, 4.5 et 4.0 indiquent l\'état général et la tranche de kilométrage, tandis que les codes de panneau comme A1 (petite rayure), U1 (légère bosse) et W2 (ondulation de peinture) marquent chaque élément. Une note R ou RA signifie un accident réparé — nous le signalons clairement avant votre décision.',
  'faq.q4': 'Quelle différence entre stock concessionnaire et véhicule d\'enchère ?',
  'faq.a4': 'Les véhicules d\'enchère se vendent un jour donné au prix du marteau en yens, alors que le stock concessionnaire est déjà tarifé chez les distributeurs japonais et se réserve immédiatement, sans attendre de session d\'enchères.',
  'faq.q5': 'AR7 peut-il sourcer un modèle précis ?',
  'faq.a5': 'Oui. Indiquez marque, modèle, plage d\'années, kilométrage maximal, couleur préférée et port de destination. Nous surveillons les listes d\'enchères quotidiennes et les réseaux japonais jusqu\'à trouver le véhicule correspondant.',
  'faq.q6': 'Que comprend le prix export ?',
  'faq.a6': 'Le prix affiché est une estimation de départ FOB (franco à bord) au Japon. Votre devis écrit détaille le prix du véhicule, le transport intérieur japonais et la préparation export, le fret maritime et l\'assurance transport (CIF).',
  'faq.q7': 'Quelle est la différence entre FOB et CIF ?',
  'faq.a7': 'Le FOB couvre le véhicule et la préparation export jusqu\'au chargement au port japonais. Le CIF (coût, assurance et fret) ajoute le fret maritime jusqu\'à votre port et l\'assurance transport, pour connaître le coût rendu port avant la douane.',
  'faq.q8': 'Comment payer et quelles devises sont acceptées ?',
  'faq.a8': 'Les achats se règlent par virement bancaire international (T/T) contre une facture proforma détaillée, généralement en USD ou JPY. Pour les enchères, un dépôt remboursable active votre limite d\'enchère et le solde est facturé après un achat réussi.',
  'faq.q9': 'Les chiffres des calculateurs du site sont-ils des devis définitifs ?',
  'faq.a9': 'Non — tous les résultats des calculateurs et délais de transit du site sont des estimations de planification. Avant tout engagement, notre bureau export au Japon émet un devis écrit avec le fret transporteur et les coûts documentaires actuels pour votre véhicule précis.',
  'faq.q10': 'Combien de temps dure l\'expédition ?',
  'faq.a10': 'Le transit maritime dépend de votre port de destination, du planning du transporteur et d\'un trajet direct ou avec transbordement. Les fenêtres de planification typiques vont d\'environ 18 à 42 jours après chargement au Japon.',
  'faq.q11': 'Dois-je choisir RoRo ou conteneur ?',
  'faq.a11': 'Le RoRo (roulier) est le choix standard et économique pour les voitures roulantes, SUV et vans. Les conteneurs dédiés ou partagés conviennent aux supercars de valeur, véhicules surbaissés ou commandes multi-véhicules.',
  'faq.q12': 'Quels documents d\'export vais-je recevoir ?',
  'faq.a12': 'Chaque expédition comprend une facture commerciale, le connaissement original (Bill of Lading), le certificat d\'export japonais (certificat de radiation) et le certificat d\'assurance maritime, plus les certificats d\'inspection pré-embarquement (QISJ, JEVIC ou EAA) si votre marché l\'exige.',
  'faq.q13': 'Comment suivre mon véhicule ?',
  'faq.a13': 'Les clients reçoivent des mises à jour par portail et WhatsApp : photos d\'arrivée au parc au Japon, inspection pré-export, réservation du navire, envoi du connaissement par courrier express et arrivée estimée au port.',
  'faq.q14': 'Qui calcule les droits d\'import et dédouane la voiture à mon port ?',
  'faq.a14': 'Les droits d\'import, taxes locales et frais d\'immatriculation sont toujours fixés par la douane de votre propre pays selon les règles locales. Votre transitaire agréé au port de destination présente les documents originaux que nous vous expédions et confirme les droits exacts à payer.',

