  'page.shippingBody': 'Zuverlässiger RoRo- und Containerversand mit Dokumentation, Versicherung und Live-Updates zu jedem Meilenstein.',
  'page.aboutKicker': 'ÜBER AR7 TRADERS',
  'page.aboutH1a': 'Ihr Team',
  'page.aboutH1b': 'vor Ort',
  'page.aboutH1em': 'in Japan.',
  'page.aboutBody': 'Wir sind Spezialisten für Fahrzeugbeschaffung — gebaut auf Transparenz, Qualität und langfristigen Kundenbeziehungen.',
  'page.contactKicker': 'SPRECHEN SIE MIT UNS',
  'page.contactH1a': 'Starten Sie Ihre',
  'page.contactH1em': 'Auto-Reise.',
  'page.contactBody': 'Nennen Sie Markt, Budget und Wunschfahrzeug. Unser Japan-Exportdesk antwortet mit passenden Optionen.',
  'page.getStarted': 'Loslegen',
  'page.sendEnquiry': 'Anfrage senden',
  'about.h2': 'Gebaut, um Ihr verlässlicher Partner zu sein.',
  'about.body': 'AR7 Traders verbindet Käufer weltweit mit der Tiefe und Qualität des japanischen Fahrzeugmarkts.',
  'about.story': 'Unser Team beschafft über die großen japanischen Auktionshäuser und vertrauenswürdige Händlernetze. Jedes Fahrzeug wird mit sorgfältiger Prüfung, klarer Kommunikation und voller Kostentransparenz ausgewählt.',
  'faq.kicker': 'HÄUFIGE FRAGEN',
  'faq.h2': 'Kaufen aus Japan, erklärt.',
  'faq.body': 'Praktische Antworten zu japanischen Auktionen, Händlerbestand, Preisen, Versand und Hafenabfertigung — nach Themen gruppiert.',
  'faq.ask': 'Weitere Frage stellen',
  'faq.topicAuctions': 'Auktionen & Zustand',
  'faq.topicPricing': 'Preise & Zahlung',
  'faq.topicShipping': 'Versand & Dokumente',
  'faq.topicArrival': 'Zoll & Ankunft',
  'faq.q1': 'Wie funktionieren japanische Autoauktionen?',
  'faq.a1': 'Lizenzierte Handelsmitglieder prüfen und bieten auf Fahrzeuge in Großhandels-Auktionshäusern in ganz Japan. AR7 wählt passende Lose aus, übersetzt die Prüfernotizen und platziert Ihr vereinbartes Maximalgebot in Ihrem Namen.',
  'faq.q2': 'Kann ich den Auktionsbericht vor dem Bieten sehen?',
  'faq.a2': 'Bei Auktionslosen ja — wir teilen den japanischen Auktionsbericht und eine verständliche Zusammenfassung der Noten und Markierungen, bevor Sie sich festlegen. Bei Händlerfahrzeugen wird der Zustand aus Händlerbericht und Platzfotos beurteilt.',
  'faq.q3': 'Was bedeuten Auktionsnoten wie 4.5, 4.0 und R?',
  'faq.a3': 'Die Noten S, 5, 4.5 und 4.0 stehen für Gesamtzustand und Laufleistungsklasse, während Panel-Codes wie A1 (kleiner Kratzer), U1 (leichte Delle) und W2 (Lackwelle) einzelne Partien markieren. Note R oder RA bedeutet reparierter Unfallschaden — wir kennzeichnen das deutlich vor Ihrer Entscheidung.',
  'faq.q4': 'Wie unterscheidet sich Händlerbestand von einem Auktionsfahrzeug?',
  'faq.a4': 'Auktionsfahrzeuge werden an einem festen Auktionstag zum Hammerpreis in Yen verkauft, während Händlerfahrzeuge bei japanischen Händlern bereits ausgepreist sind und ohne Auktionstermin sofort reserviert werden können.',
  'faq.q5': 'Kann AR7 ein bestimmtes Modell beschaffen?',
  'faq.a5': 'Ja. Nennen Sie Marke, Modell, Baujahrspanne, Kilometerlimit, Wunschfarbe und Zielhafen. Wir beobachten tägliche Auktionslisten und japanische Händlernetze, bis ein passendes Fahrzeug auftaucht.',
  'faq.q6': 'Was ist im Exportpreis enthalten?',
  'faq.a6': 'Der gelistete Preis ist eine FOB-Startschätzung (Free on Board) in Japan. Ihr schriftliches Angebot schlüsselt Fahrzeugpreis, japanischen Inlandstransport und Exportvorbereitung, Seefracht und Seetransportversicherung (CIF) auf.',
  'faq.q7': 'Was ist der Unterschied zwischen FOB und CIF?',
  'faq.a7': 'FOB deckt Fahrzeug und Exportvorbereitung bis zur Verladung im japanischen Hafen. CIF (Kosten, Versicherung, Fracht) ergänzt Seefracht bis zu Ihrem Zielhafen und Transportversicherung, sodass Sie die Kosten bis zum Hafen vor dem Zoll kennen.',
  'faq.q8': 'Wie bezahle ich und welche Währungen werden akzeptiert?',
  'faq.a8': 'Käufe werden per internationaler Banküberweisung (T/T) gegen eine aufgeschlüsselte Proforma-Rechnung beglichen, üblicherweise in USD oder JPY. Beim Auktionsbieten aktiviert eine erstattungsfähige Anzahlung Ihr Gebotslimit; der Rest wird nach erfolgreichem Kauf in Rechnung gestellt.',
  'faq.q9': 'Sind die Rechnerwerte auf der Website endgültige Angebote?',
  'faq.a9': 'Nein — alle Rechnerausgaben und Transitfenster der Website sind Planungsschätzungen. Vor Ihrer Zusage erstellt unser Japan-Exportdesk ein schriftliches Angebot mit aktuellen Frachtraten und Dokumentationskosten für Ihr konkretes Fahrzeug.',
  'faq.q10': 'Wie lange dauert der Versand?',
  'faq.a10': 'Der Seetransit hängt von Zielhafen, Carrier-Fahrplan und direkter Route oder Umladung ab. Typische Planungsfenster liegen bei rund 18 bis 42 Tagen nach Verladung in Japan.',
  'faq.q11': 'RoRo oder Containerversand?',
  'faq.a11': 'RoRo (Roll-on/Roll-off) ist die bewährte, kostengünstige Wahl für fahrbereite Autos, SUVs und Vans. Eigene oder geteilte Container eignen sich für wertvolle Supersportler, tiefe Fahrzeuge oder Händleraufträge mit mehreren Autos.',
  'faq.q12': 'Welche Exportdokumente erhalte ich?',
  'faq.a12': 'Jede Sendung umfasst Handelsrechnung, Original-Konnossement (Bill of Lading), japanisches Exportzertifikat (Abmeldebescheinigung) und Seeversicherungszertifikat, plus Vorverschiffungsinspektionen (etwa QISJ, JEVIC oder EAA), wo Ihr Markt sie verlangt.',
  'faq.q13': 'Wie verfolge ich mein Fahrzeug?',
  'faq.a13': 'Kunden erhalten Portal- und WhatsApp-Updates: Ankunftsfotos vom Platz in Japan, Vorexport-Inspektion, Schiffsbuchung, Kurierversand des Konnossements und geschätzte Hafenankunft.',
  'faq.q14': 'Wer berechnet den Einfuhrzoll und fertigt das Auto an meinem Hafen ab?',
  'faq.a14': 'Einfuhrzoll, lokale Steuern und Zulassungsgebühren legt stets die Zollbehörde Ihres eigenen Landes nach lokalen Regeln fest. Ihr lizenzierter Zollagent am Zielhafen reicht die von uns zugesandten Originaldokumente ein und bestätigt den exakten Zollbetrag.',

  // 2026-11-13: How-to-Buy flow, Services tabs/panel, Tools calculators, destinations hub
  'svc.1t': 'Auktions-Sourcing',
  'svc.1p': 'Live-Zugang zu USS, TAA, JU, CAA und mehr.',
  'svc.1s': '100,000+ Inserate pro Woche',
  'svc.2t': 'Händlerbestand',
  'svc.2p': 'Ausgewählte Fahrzeuge abseits der Auktion aus vertrauten Netzwerken.',
  'svc.2s': 'Schnelle Kaufentscheidungen',
