  'dest.hubNoteBody': 'ввозную пошлину, местные налоги и регистрационные сборы всегда определяет таможня вашей страны в порту прибытия — мы готовим полный пакет экспортных документов для вашего брокера и никогда не называем ставку пошлины.',
