  'page.aboutH1a': 'Tu equipo',
  'page.aboutH1b': 'en el terreno',
  'page.aboutH1em': 'en Japón.',
  'page.aboutBody': 'Somos especialistas en abastecimiento vehicular, construidos sobre transparencia, calidad y relaciones duraderas.',
  'page.contactKicker': 'HABLA CON NUESTRO EQUIPO',
  'page.contactH1a': 'Comienza tu',
  'page.contactH1em': 'viaje automotor.',
  'page.contactBody': 'Cuéntanos tu mercado, presupuesto y vehículo preferido. Nuestra mesa de exportación en Japón responderá con opciones adecuadas.',
  'page.getStarted': 'Comenzar',
  'page.sendEnquiry': 'Enviar consulta',
  'about.h2': 'Hechos para ser tu socio de confianza.',
  'about.body': 'AR7 Traders conecta a compradores de todo el mundo con la profundidad y calidad del mercado vehicular japonés.',
  'about.story': 'Nuestro equipo compra en las grandes casas de subastas japonesas y redes de concesionarios confiables. Cada vehículo se elige con inspección cuidadosa, comunicación clara y total transparencia de costos.',
  'faq.kicker': 'PREGUNTAS FRECUENTES',
  'faq.h2': 'Comprar desde Japón, explicado.',
  'faq.body': 'Respuestas prácticas sobre subastas japonesas, stock de concesionarios, precios, envío y despacho portuario — agrupadas por tema.',
  'faq.ask': 'Haz otra pregunta',
  'faq.topicAuctions': 'Subastas y condición',
  'faq.topicPricing': 'Precios y pago',
  'faq.topicShipping': 'Envío y documentos',
  'faq.topicArrival': 'Aduana y llegada',
  'faq.q1': '¿Cómo funcionan las subastas de autos japonesas?',
  'faq.a1': 'Miembros comerciales licenciados inspeccionan y pujan por vehículos en casas de subastas mayoristas de todo Japón. AR7 preselecciona lotes adecuados, traduce las notas del inspector y coloca tu puja máxima acordada en tu nombre.',
  'faq.q2': '¿Puedo ver la ficha de subasta antes de pujar?',
  'faq.a2': 'Para lotes de subasta, sí — compartimos la ficha japonesa y un resumen claro de grados y marcas antes de que te comprometas. Para vehículos de concesionario, la condición se revisa con el informe del vendedor y fotos del patio.',
  'faq.q3': '¿Qué significan los grados 4.5, 4.0 y R?',
  'faq.a3': 'Los grados S, 5, 4.5 y 4.0 indican condición general y rango de kilometraje, mientras códigos de panel como A1 (rayón pequeño), U1 (abolladura leve) y W2 (onda de pintura) marcan paneles individuales. Un grado R o RA significa accidente reparado — lo señalamos claramente antes de que decidas.',
  'faq.q4': '¿En qué difiere el stock de concesionario de un auto de subasta?',
  'faq.a4': 'Los autos de subasta se venden en un día programado al precio de martillo en yenes, mientras que el stock de concesionario ya está tasado en Japón y se reserva de inmediato, sin esperar sesión de subasta.',
  'faq.q5': '¿Puede AR7 conseguir un modelo específico?',
  'faq.a5': 'Sí. Comparte marca, modelo, rango de años, tope de kilometraje, color preferido y puerto de destino. Monitoreamos listas diarias de subasta y redes japonesas hasta que aparezca el vehículo indicado.',
  'faq.q6': '¿Qué incluye el precio de exportación?',
  'faq.a6': 'El precio listado es una estimación inicial FOB (libre a bordo) en Japón. Tu cotización escrita detalla el precio del vehículo, transporte interno japonés y preparación de exportación, flete marítimo y seguro de tránsito (CIF).',
  'faq.q7': '¿Cuál es la diferencia entre FOB y CIF?',
  'faq.a7': 'FOB cubre el vehículo y la preparación hasta la carga en el puerto japonés. CIF (costo, seguro y flete) agrega el flete marítimo a tu puerto y el seguro de tránsito, para ver el costo puesto en puerto antes de aduanas.',
  'faq.q8': '¿Cómo pago y qué monedas se aceptan?',
  'faq.a8': 'Las compras se liquidan por transferencia bancaria internacional (T/T) contra una factura proforma detallada, normalmente en USD o JPY. Para pujar, un depósito reembolsable activa tu límite y el saldo se factura tras una compra exitosa.',
  'faq.q9': '¿Los números de las calculadoras son cotizaciones finales?',
  'faq.a9': 'No — todos los resultados de calculadoras y tiempos de tránsito del sitio son estimaciones de planificación. Antes de comprometerte, nuestra mesa de exportación emite una cotización escrita con el flete vigente y costos documentales para tu vehículo específico.',
  'faq.q10': '¿Cuánto tarda el envío?',
  'faq.a10': 'El tránsito marítimo depende de tu puerto de destino, el itinerario del naviero y si el buque va directo o con transbordo. Las ventanas típicas van de unos 18 a 42 días tras la carga en Japón.',
  'faq.q11': '¿Elijo RoRo o contenedor?',
  'faq.a11': 'RoRo (Roll-on/Roll-off) es la opción estándar y económica para autos que ruedan, SUVs y vans. Los contenedores dedicados o compartidos convienen a superautos valiosos, vehículos bajos o pedidos múltiples de concesionarios.',
  'faq.q12': '¿Qué documentos de exportación recibiré?',
  'faq.a12': 'Cada envío se prepara con factura comercial, Bill of Lading original, certificado de exportación japonés (certificado de baja) y certificado de seguro marítimo, más certificados de inspección previa al embarque (QISJ, JEVIC o EAA) donde tu mercado lo exija.',
  'faq.q13': '¿Cómo rastreo mi vehículo?',
  'faq.a13': 'Los clientes reciben actualizaciones por portal y WhatsApp: fotos de llegada al patio en Japón, inspección pre-exportación, reserva del buque, despacho del Bill of Lading por courier y llegada estimada al puerto.',
  'faq.q14': '¿Quién calcula el arancel y despacha el auto en mi puerto?',
  'faq.a14': 'El arancel de importación, impuestos locales y tasas de registro siempre los determina la aduana de tu propio país según reglas locales. Tu agente aduanal licenciado en destino presenta los documentos originales que te enviamos y confirma el monto exacto a pagar.',

