  'hb.s5w': 'Cuando el vehículo llega a nuestro patio de exportación en Japón, fotografiamos exterior, interior y bajos, completamos cualquier inspección obligatoria previa al embarque (como QISJ, JEVIC o limpieza de bioseguridad) y lo preparamos para la carga.',
