  'page.aboutBody': 'Somos especialistas em aquisição de veículos, construídos sobre transparência, qualidade e relações duradouras com clientes.',
  'page.contactKicker': 'FALE COM NOSSA EQUIPE',
  'page.contactH1a': 'Comece sua',
  'page.contactH1em': 'jornada automotiva.',
  'page.contactBody': 'Diga seu mercado, orçamento e veículo preferido. Nossa mesa de exportação no Japão responderá com boas opções.',
  'page.getStarted': 'Começar',
  'page.sendEnquiry': 'Enviar consulta',
  'about.h2': 'Feitos para ser seu parceiro de confiança.',
  'about.body': 'A AR7 Traders conecta compradores do mundo todo à profundidade e qualidade do mercado automotivo japonês.',
  'about.story': 'Nossa equipe compra nas grandes casas de leilão japonesas e em redes confiáveis de concessionárias. Cada veículo é escolhido com inspeção cuidadosa, comunicação clara e total transparência de custos.',
  'faq.kicker': 'PERGUNTAS FREQUENTES',
  'faq.h2': 'Comprar do Japão, explicado.',
  'faq.body': 'Respostas práticas sobre leilões japoneses, estoque de concessionárias, preços, envio e desembaraço no porto — agrupadas por tema.',
  'faq.ask': 'Fazer outra pergunta',
  'faq.topicAuctions': 'Leilões e condição',
  'faq.topicPricing': 'Preços e pagamento',
  'faq.topicShipping': 'Envio e documentos',
  'faq.topicArrival': 'Alfândega e chegada',
  'faq.q1': 'Como funcionam os leilões de carros japoneses?',
  'faq.a1': 'Membros comerciais licenciados inspecionam e dão lances em veículos nas casas de leilão atacadistas de todo o Japão. A AR7 seleciona lotes adequados, traduz as notas do inspetor e registra seu lance máximo combinado em seu nome.',
  'faq.q2': 'Posso ver a ficha do leilão antes do lance?',
  'faq.a2': 'Para lotes de leilão, sim — compartilhamos a ficha japonesa e um resumo claro das notas e marcas antes de você se comprometer. Para veículos de concessionária, a condição é avaliada pelo relatório do vendedor e fotos do pátio.',
  'faq.q3': 'O que significam as notas 4.5, 4.0 e R?',
  'faq.a3': 'Notas S, 5, 4.5 e 4.0 indicam condição geral e faixa de quilometragem, enquanto códigos de painel como A1 (risco pequeno), U1 (amassado leve) e W2 (ondulação de pintura) marcam painéis individuais. Nota R ou RA indica acidente reparado — sinalizamos claramente antes da sua decisão.',
  'faq.q4': 'Qual a diferença entre estoque de concessionária e carro de leilão?',
  'faq.a4': 'Carros de leilão são vendidos em dia marcado pelo preço de martelo em ienes, enquanto o estoque de concessionária já tem preço no Japão e pode ser reservado na hora, sem esperar sessão de leilão.',
  'faq.q5': 'A AR7 consegue um modelo específico?',
  'faq.a5': 'Sim. Informe marca, modelo, faixa de anos, teto de quilometragem, cor preferida e porto de destino. Monitoramos as listas diárias de leilão e as redes japonesas até surgir o veículo certo.',
  'faq.q6': 'O que está incluído no preço de exportação?',
  'faq.a6': 'O preço listado é uma estimativa inicial FOB (Free on Board) no Japão. Sua cotação escrita detalha o preço do veículo, transporte interno japonês e preparação de exportação, frete marítimo e seguro de trânsito (CIF).',
  'faq.q7': 'Qual a diferença entre FOB e CIF?',
  'faq.a7': 'FOB cobre o veículo e a preparação até o embarque no porto japonês. CIF (custo, seguro e frete) adiciona o frete marítimo até seu porto e o seguro de trânsito, mostrando o custo posto no porto antes da alfândega.',
  'faq.q8': 'Como pago e quais moedas são aceitas?',
  'faq.a8': 'As compras são liquidadas por transferência bancária internacional (T/T) contra fatura proforma detalhada, normalmente em USD ou JPY. Para lances, um depósito reembolsável ativa seu limite e o saldo é faturado após a compra bem-sucedida.',
  'faq.q9': 'Os números das calculadoras são cotações finais?',
  'faq.a9': 'Não — todos os resultados das calculadoras e janelas de trânsito do site são estimativas de planejamento. Antes de fechar, nossa mesa de exportação emite cotação escrita com o frete atual e custos documentais para o seu veículo específico.',
  'faq.q10': 'Quanto tempo leva o envio?',
  'faq.a10': 'O trânsito marítimo depende do porto de destino, da programação do armador e de rota direta ou com transbordo. As janelas típicas vão de cerca de 18 a 42 dias após o embarque no Japão.',
  'faq.q11': 'Escolho RoRo ou contêiner?',
  'faq.a11': 'RoRo (Roll-on/Roll-off) é a escolha padrão e econômica para carros que rodam, SUVs e vans. Contêineres dedicados ou compartilhados servem para superesportivos valiosos, veículos rebaixados ou pedidos múltiplos de lojas.',
  'faq.q12': 'Quais documentos de exportação vou receber?',
  'faq.a12': 'Cada embarque é preparado com fatura comercial, Bill of Lading original, certificado de exportação japonês (baixa de registro) e certificado de seguro marítimo, além de certificados de inspeção pré-embarque (QISJ, JEVIC ou EAA) onde seu mercado exigir.',
  'faq.q13': 'Como acompanho meu veículo?',
  'faq.a13': 'Clientes recebem atualizações pelo portal e WhatsApp: fotos da chegada ao pátio no Japão, inspeção pré-exportação, reserva do navio, envio do Bill of Lading por courier e chegada estimada ao porto.',
  'faq.q14': 'Quem calcula o imposto e libera o carro no meu porto?',
  'faq.a14': 'Imposto de importação, tributos locais e taxas de registro são sempre definidos pela alfândega do seu país conforme as regras locais. Seu despachante licenciado no porto de destino apresenta os documentos originais que enviamos e confirma o valor exato devido.',

