  'hb.s1t': 'Conte-nos o carro',
  'hb.s1p': 'Informe marca, modelo, ano, orçamento e porto de destino. Pré-selecionamos estoque e lotes de leilão.',
  'hb.s1w': 'Nossa mesa de exportação no Japão confere os calendários de leilão ao vivo e o estoque de concessionárias com as regras de idade e conformidade do seu país de destino antes de enviar a pré-seleção.',
