  'hb.s2w': 'Para lotes de leilão, um especialista baseado no Japão traduz as anotações manuscritas do inspetor, as notas dos painéis e as marcações internas para uma linguagem clara; para estoque de concessionária, compartilhamos as notas de estado e o conjunto de fotos.',
  'hb.s3t': 'Defina um teto de lance',
