  'page.contactH1em': 'başlatın.',
  'page.contactBody': 'Pazarınızı, bütçenizi ve tercih ettiğiniz aracı söyleyin. Japonya ihracat masamız uygun seçeneklerle dönecek.',
  'page.getStarted': 'Başlayın',
  'page.sendEnquiry': 'Talep gönderin',
  'about.h2': 'Güvenilir ortağınız olmak için kurulduk.',
  'about.body': 'AR7 Traders, dünyanın dört bir yanındaki alıcıları Japon araç pazarının derinliği ve kalitesiyle buluşturur.',
  'about.story': 'Ekibimiz büyük Japon müzayede evleri ve güvenilir bayi ağları üzerinden tedarik eder. Her araç titiz muayene, net iletişim ve tam maliyet şeffaflığıyla seçilir.',
  'faq.kicker': 'POPÜLER SORULAR',
  'faq.h2': 'Japonya\'dan almak, açıklandı.',
  'faq.body': 'Japon müzayedeleri, bayi stoğu, fiyatlar, sevkiyat ve liman gümrüğü üzerine pratik cevaplar — konuya göre gruplu.',
  'faq.ask': 'Başka bir soru sorun',
  'faq.topicAuctions': 'Müzayede ve durum',
  'faq.topicPricing': 'Fiyat ve ödeme',
  'faq.topicShipping': 'Sevkiyat ve belgeler',
  'faq.topicArrival': 'Gümrük ve varış',
  'faq.q1': 'Japon araba müzayedeleri nasıl çalışır?',
  'faq.a1': 'Lisanslı ticari üyeler, Japonya genelindeki toptan müzayede evlerinde araçları inceler ve teklif verir. AR7 uygun lotları kısa listeye alır, eksper notlarını çevirir ve anlaşılan azami teklifinizi sizin adınıza verir.',
  'faq.q2': 'Teklif vermeden önce müzayede raporunu görebilir miyim?',
  'faq.a2': 'Müzayede lotları için evet — teklife bağlanmadan önce Japonca müzayede raporunu ve not ile işaretlerin sade bir özetini paylaşırız. Bayi stoğu araçlarda durum, bayi raporu ve saha fotoğraflarından değerlendirilir.',
  'faq.q3': '4.5, 4.0 ve R gibi müzayede notları ne anlama gelir?',
  'faq.a3': 'S, 5, 4.5 ve 4.0 notları genel durumu ve kilometre bandını gösterir; A1 (küçük çizik), U1 (hafif göçük) ve W2 (boya dalgası) gibi panel kodları tek tek panelleri işaretler. R veya RA notu onarılmış kaza geçmişi demektir — karar vermeden önce bunu açıkça belirtiriz.',
  'faq.q4': 'Bayi stoğu, müzayede aracından nasıl farklıdır?',
  'faq.a4': 'Müzayede araçları belirlenen ihale gününde Japon yeni üzerinden çekiç fiyatıyla satılır; bayi stoğu araçlar ise Japon bayilerinde zaten fiyatlandırılmıştır ve müzayede beklemeden hemen rezerve edilebilir.',
  'faq.q5': 'AR7 belirli bir modeli tedarik edebilir mi?',
  'faq.a5': 'Evet. Hedef marka, model, yıl aralığı, kilometre üst sınırı, renk tercihi ve varış limanınızı paylaşın. Uygun araç çıkana kadar günlük müzayede listelerini ve Japon bayi ağlarını izleriz.',
  'faq.q6': 'İhracat fiyatına neler dahildir?',
  'faq.a6': 'Listelenen fiyat, Japonya\'da FOB (gemide teslim) başlangıç tahminidir. Yazılı teklifiniz araç fiyatını, Japonya içi nakliye ve ihracat hazırlığını, deniz navlununu ve deniz nakliye sigortasını (CIF) kalem kalem gösterir.',
  'faq.q7': 'FOB ile CIF fiyatlandırması arasındaki fark nedir?',
  'faq.a7': 'FOB, aracı ve ihracat hazırlığını Japon limanında yüklemeye kadar kapsar. CIF (maliyet, sigorta ve navlun) varış limanınıza deniz navlununu ve nakliye sigortasını ekler; böylece gümrükten önce limana inmiş maliyeti görürsünüz.',
  'faq.q8': 'Aracı nasıl öderim, hangi para birimleri kabul edilir?',
  'faq.a8': 'Alımlar, kalemli proforma fatura karşılığında uluslararası banka havalesiyle (T/T) genellikle USD veya JPY olarak kapatılır. Müzayede teklifi için iade edilebilir depozito teklif limitinizi etkinleştirir; bakiye başarılı alımdan sonra faturalanır.',
  'faq.q9': 'Sitedeki hesaplayıcı rakamları kesin teklif midir?',
  'faq.a9': 'Hayır — sitedeki tüm hesaplayıcı çıktıları ve transit süreleri planlama tahminidir. Bağlanmadan önce Japonya ihracat masamız, aracınıza özel güncel navlun ve evrak maliyetleriyle yazılı teklif düzenler.',
  'faq.q10': 'Sevkiyat ne kadar sürer?',
  'faq.a10': 'Deniz transiti varış limanınıza, taşıyıcının programına ve geminin direkt ya da aktarmalı gitmesine bağlıdır. Tipik planlama aralığı, Japonya\'da yüklemeden sonra yaklaşık 18–42 gündür.',
  'faq.q11': 'RoRo mu konteyner mi seçmeliyim?',
  'faq.a11': 'RoRo (sür-indir) yürür durumdaki arabalar, SUV\'lar ve minibüsler için standart ve ekonomik seçimdir. Özel veya paylaşımlı konteynerler değerli süper arabalara, basık araçlara veya çok araçlı bayi siparişlerine uygundur.',
  'faq.q12': 'Hangi ihracat belgelerini alacağım?',
  'faq.a12': 'Her sevkiyat ticari fatura, orijinal konşimento (Bill of Lading), Japon İhracat Sertifikası (kayıt silme belgesi) ve deniz sigortası sertifikasıyla hazırlanır; pazarınız gerektiriyorsa sevkiyat öncesi muayene sertifikaları (QISJ, JEVIC veya EAA) da eklenir.',
  'faq.q13': 'Aracımı nasıl takip ederim?',
  'faq.a13': 'Müşteriler portal ve WhatsApp üzerinden güncelleme alır: Japonya\'da sahaya varış fotoğrafları, ihracat öncesi muayene, gemi rezervasyonu, konşimentonun kuryeyle gönderimi ve tahmini liman varışı.',
  'faq.q14': 'İthalat vergisini kim hesaplar, aracı limanımda kim çeker?',
  'faq.a14': 'İthalat vergisi, yerel vergiler ve tescil ücretleri her zaman kendi ülkenizin gümrük idaresince yerel kurallara göre belirlenir. Varış limanındaki lisanslı gümrük müşaviriniz, kuryeyle gönderdiğimiz orijinal belgeleri ibraz eder ve ödenecek kesin vergiyi teyit eder.',

