  'faq.q1': '日本汽车拍卖如何运作？',
  'faq.a1': '持牌贸易会员在日本各地的批发拍卖行检验车辆并出价。AR7 为您筛选合适的拍品、翻译检查员笔记，并代您按约定上限出价。',
  'faq.q2': '出价前能看到拍卖检查表吗？',
  'faq.a2': '拍卖车源可以——在您决定出价前，我们会分享日文拍卖检查表及评分与标记的通俗摘要。经销商库存车辆则依据经销商报告和场地照片评估车况。',
  'faq.q3': '4.5、4.0、R 这些拍卖评分是什么意思？',
  'faq.a3': 'S、5、4.5、4.0 表示整体车况与里程区间；A1（小划痕）、U1（小凹陷）、W2（漆面波纹）等代码标注各个部位。R 或 RA 评分表示有修复过的事故史——我们会在您决定前明确标出。',
  'faq.q4': '经销商库存和拍卖车有什么不同？',
  'faq.a4': '拍卖车在既定竞拍日以日元落槌价成交；经销商库存车在日本门店已有标价，无需等待拍卖即可立即预订。',
  'faq.q5': 'AR7 能找特定车型吗？',
  'faq.a5': '可以。告诉我们目标品牌、车型、年份范围、里程上限、偏好颜色与目的港。我们会持续盯每日拍卖列表和日本经销网络，直到匹配车辆出现。',
  'faq.q6': '出口价格包含什么？',
  'faq.a6': '所列车价是日本 FOB（离岸价）起始估算。书面报价单逐项列明车价、日本境内运输与出口整备、海运费及海运保险（CIF）。',
  'faq.q7': 'FOB 和 CIF 定价有何区别？',
  'faq.a7': 'FOB 涵盖车辆及出口整备，直至在日本港口装船。CIF（成本、保险加运费）再加上到您目的港的海运费和运输保险，让您在清关前就知道到港成本。',
  'faq.q8': '怎么付款？接受哪些货币？',
  'faq.a8': '购车凭逐项列明的形式发票以国际电汇（T/T）结算，通常用美元或日元。拍卖竞价时，可退还的押金激活您的出价额度，成交后再开票结清余款。',
  'faq.q9': '网站计算器的数字是最终报价吗？',
  'faq.a9': '不是——网站上所有计算器结果和运输周期都是规划估算。在您决定前，我们的日本出口团队会按您的具体车辆出具载明当前船运费和文件费用的书面报价。',
  'faq.q10': '海运要多久？',
  'faq.a10': '海上运输取决于目的港、船期以及直航还是中转。常见规划周期为日本装船后约 18 至 42 天。',
  'faq.q11': '选 RoRo 还是集装箱？',
  'faq.a11': 'RoRo（滚装船）是可行驶轿车、SUV 和面包车的标准经济之选。独立或拼箱集装箱适合高价值超跑、低底盘车辆或经销商多车订单。',
  'faq.q12': '我会收到哪些出口文件？',
  'faq.a12': '每批货物都备妥商业发票、正本提单（Bill of Lading）、日本出口证明（注销登记证明）和海运保险证书；若您的市场要求，还包括装运前检验证书（如 QISJ、JEVIC 或 EAA）。',
  'faq.q13': '如何追踪我的车辆？',
  'faq.a13': '客户通过门户和 WhatsApp 接收更新：日本场地到场照片、出口前检验、订舱、提单快递寄出与预计到港时间。',
  'faq.q14': '进口关税由谁核算？谁在我的港口清关？',
  'faq.a14': '进口关税、当地税费和登记费始终由您所在国家的海关按当地规定核定。目的港的持牌清关代理凭我们快递给您的正本文件办理，并确认应缴的准确税额。',

