  'page.aboutH1em': 'Japani.',
  'page.aboutBody': 'Sisi ni wataalamu wa upatikanaji wa magari, tuliojengwa juu ya uwazi, ubora na mahusiano ya muda mrefu na wateja.',
  'page.contactKicker': 'ZUNGUMZA NA TIMU YETU',
