  'page.contactBody': 'Tuambie soko lako, bajeti na gari unalopendelea. Deski letu la usafirishaji Japani litajibu na chaguo zinazofaa.',
  'page.getStarted': 'Anza sasa',
  'page.sendEnquiry': 'Tuma hoja',
  'about.h2': 'Tumejengwa kuwa mshirika wako wa kuaminika.',
  'about.body': 'AR7 Traders huwaunganisha wanunuzi duniani kote na kina na ubora wa soko la magari la Japani.',
  'about.story': 'Timu yetu hununua kupitia nyumba kubwa za minada za Japani na mitandao ya madalali ya kuaminika. Kila gari huchaguliwa kwa ukaguzi makini, mawasiliano wazi na uwazi kamili wa gharama.',
  'faq.kicker': 'MASWALI MAARUFU',
  'faq.h2': 'Kununua kutoka Japani, kumefafanuliwa.',
  'faq.body': 'Majibu ya vitendo kuhusu minada ya Japani, stoo ya madalali, bei, usafirishaji na utoaji bandarini — yamepangwa kwa mada.',
  'faq.ask': 'Uliza swali lingine',
  'faq.topicAuctions': 'Minada na hali',
  'faq.topicPricing': 'Bei na malipo',
  'faq.topicShipping': 'Usafirishaji na hati',
  'faq.topicArrival': 'Forodha na kuwasili',
  'faq.q1': 'Minada ya magari ya Japani inafanyaje kazi?',
  'faq.a1': 'Wanachama wa biashara wenye leseni hukagua na kuweka zabuni kwa magari katika nyumba za minada za jumla kote Japani. AR7 huchagua loti zinazofaa, hutafsiri maelezo ya mkaguzi na kuweka zabuni yako ya juu iliyokubaliwa kwa niaba yako.',
  'faq.q2': 'Naweza kuona karatasi ya mnada kabla ya zabuni?',
  'faq.a2': 'Kwa loti za mnada, ndiyo — tunashiriki karatasi ya mnada ya Kijapani na muhtasari rahisi wa madaraja na alama kabla hujajifunga kwenye zabuni. Kwa magari ya stoo ya madalali, hali hukaguliwa kutoka ripoti ya dalali na picha za uwanjani.',
  'faq.q3': 'Madaraja ya mnada kama 4.5, 4.0 na R yanamaanisha nini?',
  'faq.a3': 'Madaraja S, 5, 4.5 na 4.0 huonyesha hali ya jumla na kiwango cha kilomita, huku misimbo ya paneli kama A1 (mkwaruzo mdogo), U1 (bonyeo dogo) na W2 (wimbi la rangi) ikiashiria paneli moja moja. Daraja la R au RA linamaanisha historia ya ajali iliyorekebishwa — tunaliweka wazi kabla hujafanya uamuzi.',
  'faq.q4': 'Stoo ya madalali inatofautianaje na gari la mnada?',
  'faq.a4': 'Magari ya mnada huuzwa siku maalum ya zabuni kwa bei ya nyundo kwa yen ya Japani, wakati magari ya stoo ya madalali tayari yana bei katika maduka ya Japani na yanaweza kuhifadhiwa papo hapo bila kusubiri kikao cha mnada.',
  'faq.q5': 'AR7 inaweza kutafuta modeli maalum?',
  'faq.a5': 'Ndiyo. Shiriki chapa, modeli, upeo wa miaka, kikomo cha kilomita, rangi unayopendelea na bandari ya mwisho. Tunafuatilia orodha za minada za kila siku na mitandao ya madalali ya Japani hadi gari linalolingana lipatikane.',
  'faq.q6': 'Nini kimo ndani ya bei ya usafirishaji?',
  'faq.a6': 'Bei ya gari iliyoorodheshwa ni makadirio ya kuanzia ya FOB (Free on Board) Japani. Nukuu yako ya maandishi huainisha bei ya gari, usafiri wa ndani wa Japani na maandalizi ya usafirishaji, nauli ya baharini na bima ya usafiri wa baharini (CIF).',
  'faq.q7': 'Tofauti kati ya bei ya FOB na CIF ni ipi?',
  'faq.a7': 'FOB inagharamia gari na maandalizi ya usafirishaji hadi kupakiwa bandari ya Japani. CIF (Gharama, Bima na Nauli) huongeza nauli ya baharini hadi bandari yako na bima ya usafiri, ili uone gharama ya kufika bandarini kabla ya forodha.',
  'faq.q8': 'Nalipaje gari na sarafu zipi zinakubaliwa?',
  'faq.a8': 'Ununuzi hulipwa kwa uhamisho wa benki wa kimataifa (T/T) dhidi ya ankara ya proforma iliyoainishwa, kwa kawaida kwa USD au JPY. Kwa zabuni za mnada, amana inayorejeshwa huwasha kikomo chako cha zabuni na salio hutozwa baada ya ununuzi kufanikiwa.',
  'faq.q9': 'Je, namba za vikokotoo kwenye tovuti ni nukuu za mwisho?',
  'faq.a9': 'Hapana — matokeo yote ya vikokotoo na mida ya safari kwenye tovuti ni makadirio ya kupanga. Kabla hujajifunga, deski letu la usafirishaji Japani hutoa nukuu ya maandishi yenye nauli za sasa za msafirishaji na gharama za hati kwa gari lako mahususi.',
  'faq.q10': 'Usafirishaji huchukua muda gani?',
  'faq.a10': 'Safari ya baharini inategemea bandari yako ya mwisho, ratiba ya msafirishaji na kama meli inaenda moja kwa moja au inabadilisha meli. Mida ya kawaida ya kupanga ni takriban siku 18 hadi 42 baada ya kupakia Japani.',
  'faq.q11': 'Nichague RoRo au usafirishaji wa kontena?',
  'faq.a11': 'RoRo (Roll-on/Roll-off) ndiyo chaguo la kawaida na la gharama nafuu kwa magari yanayoendeshwa, SUV na vani. Kontena maalum au za kushirikiana zinafaa kwa supercar za thamani kubwa, magari ya chini au oda za magari mengi za maduka.',
  'faq.q12': 'Nitapokea hati zipi za usafirishaji?',
  'faq.a12': 'Kila shehena huandaliwa na Ankara ya Biashara, Bill of Lading halisi, Cheti cha Usafirishaji cha Japani (cheti cha kufuta usajili) na cheti cha bima ya baharini, pamoja na vyeti vya ukaguzi kabla ya kusafirisha (kama QISJ, JEVIC au EAA) pale soko lako linapohitaji.',
  'faq.q13': 'Nafuatiliaje gari langu?',
  'faq.a13': 'Wateja hupokea sasisho za tovuti na WhatsApp zinazojumuisha picha za kuwasili uwanjani Japani, ukaguzi kabla ya usafirishaji, uhifadhi wa meli, utumaji wa Bill of Lading kwa courier na makadirio ya kuwasili bandarini.',
  'faq.q14': 'Nani huhesabu ushuru wa uagizaji na kutoa gari bandari yangu?',
  'faq.a14': 'Ushuru wa uagizaji, kodi za ndani na ada za usajili daima huamuliwa na mamlaka ya forodha ya nchi yako kwa kanuni za ndani. Wakala wako wa forodha mwenye leseni katika bandari ya mwisho huwasilisha hati halisi tunazokutumia na kuthibitisha ushuru kamili unaostahili.',

