  'dest.transit': 'Makadirio ya safari (takwimu ya kupanga):',
  'dest.popular': 'MAARUFU:',
  'hb.s1t': 'Tuambie gari unalotaka',
  'hb.s1p': 'Tuma aina, modeli, mwaka, bajeti na bandari ya kufikia. Tunachagua stoo na mnada vinavyolingana.',
  'hb.s1w': 'Dawati letu la usafirishaji nchini Japani hukagua ratiba za minada za moja kwa moja na stoo za madalali dhidi ya sheria za umri na uafikiano za nchi yako kabla ya kukutumia orodha fupi.',
  'hb.s2t': 'Pokea karatasi zilizotafsiriwa',
  'hb.s2p': 'Muhtasari kamili wa Kiingereza wa kila karatasi ya mnada, na picha za alama na dalili za ukarabati.',
  'hb.s2w': 'Kwa magari ya mnada, mtaalamu aliyeko Japani hutafsiri maandishi ya mkaguzi, madaraja ya paneli na alama za ndani kwa lugha rahisi; kwa stoo ya dalali, tunashiriki maelezo ya hali ya dalali na seti ya picha.',
  'hb.s3t': 'Weka kikomo cha zabuni',
  'hb.s3p': 'Kubaliana kiwango cha juu thabiti kabla ya kuzabuni — hakuna mshangao, hakuna kupandishwa.',
  'hb.s3w': 'Unathibitisha kwa maandishi zabuni ya juu kabisa kwa JPY au USD pamoja na mchanganuo wa makadirio ya gharama ya CIF, nasi tunafunga kikomo hicho kabla gari halijaingia kwenye mstari wa mnada.',
  'hb.s4t': 'Tunazabuni kwa niaba yako',
  'hb.s4p': 'Mawakala wetu huzabuni moja kwa moja USS, TAA, JU, CAA na mingine; wewe unafuatilia kwenye tovuti yako.',
  'hb.s4w': 'Dawati letu la zabuni huweka zabuni za moja kwa moja ukumbini au kupitia terminali hadi kikomo chako kilichokubaliwa, na kushiriki matokeo ya nyundo mara tu mnada unapofungwa.',
  'hb.s5t': 'Kagua na kuandaa',
  'hb.s5p': 'Picha huru za uwanjani, ukaguzi wa chini ya gari, ulinganisho wa hali na karatasi ya mnada au ripoti ya dalali, na maandalizi kabla ya usafirishaji.',
  'hb.s5w': 'Gari linapofika uwanja wetu wa usafirishaji nchini Japani, tunapiga picha nje, ndani na chini ya gari, tunakamilisha ukaguzi wowote wa lazima kabla ya kusafirisha (kama QISJ, JEVIC au usafi wa kibiolojia), na kuliandaa kwa upakiaji.',
  'hb.s6t': 'Lipa kwa hatua',
  'hb.s6p': 'Amana huwasha zabuni; salio hugawanywa kabla na baada ya usafirishaji kulingana na ankara yako.',
  'hb.s6w': 'Unapokea ankara ya proforma iliyochanganuliwa inayoonyesha bei ya gari, maandalizi ya usafirishaji, nauli na bima ya baharini, inayolipwa kwa uhamisho wa benki (T/T) huku kila malipo yakirekodiwa kwenye akaunti yako.',
  'hb.s7t': 'Nyaraka za usafirishaji',
  'hb.s7p': 'Ankara, cheti cha usafirishaji, hati ya mzigo, bima — zote zinashughulikiwa na dawati letu.',
  'hb.s7w': 'Tunakamilisha ufutaji wa usajili wa Kijapani (Cheti cha Usafirishaji / Yushutsu Massho), tunatoa Ankara ya Kibiashara na cheti cha bima ya baharini, na kutuma Hati Halisi ya Mzigo kupitia DHL.',
  'hb.s8t': 'Fuatilia hadi bandari yako',
  'hb.s8p': 'Hatua za moja kwa moja kutoka uwanja wa Japani hadi bandari yako, na nyaraka tayari kwa forodha zinapofika.',
  'hb.s8w': 'Unafuatilia kuondoka kwa meli na makadirio ya kuwasili kwenye akaunti yako, huku wakala wako wa forodha wa ndani akitumia kifurushi cha nyaraka kilichotumwa kusafisha mizigo bandarini kwako.',
  'hb.tlKicker': 'RATIBA YA KUPANGA',
  'hb.tlH2': 'Siku za kawaida kutoka zabuni hadi uwasilishaji.',
  'hb.d1': 'Siku ya 1',
