  'page.aboutKicker': 'GAME DA AR7 TRADERS',
  'page.aboutH1a': 'Tawagarka',
  'page.aboutH1b': 'a wurin aiki',
  'page.aboutH1em': 'a Japan.',
  'page.aboutBody': 'Mu kwararru ne kan samar da motoci, da aka gina a kan gaskiya, inganci da dangantaka mai dorewa da abokan ciniki.',
  'page.contactKicker': 'TATTAUNA DA TAWAGARMU',
  'page.contactH1a': 'Fara tafiyar',
  'page.contactH1em': 'motarka.',
  'page.contactBody': 'Fada mana kasuwarka, kasafinka da motar da kake so. Teburin fitarwarmu na Japan zai amsa da zabukan da suka dace.',
  'page.getStarted': 'Fara',
  'page.sendEnquiry': 'Aika tambaya',
  'about.h2': 'An gina mu don zama amintaccen abokin tafiyarka.',
  'about.body': 'AR7 Traders na hada masu saye a duniya da zurfi da ingancin kasuwar motocin Japan.',
  'about.story': 'Tawagarmu na saye ta manyan gidajen gwanjo na Japan da amintattun hanyoyin dila. Ana zabar kowace mota da bincike na tsanaki, sadarwa bayyananna da cikakken fitowar kudade fili.',
  'faq.kicker': 'TAMBAYOYIN DA AKA FI YI',
  'faq.h2': 'Saye daga Japan, an bayyana.',
  'faq.body': 'Amsoshi masu amfani kan gwanjon Japan, hajojin dila, farashi, jigila da fitar da kaya a tasha — an tsara su bisa jigo.',
  'faq.ask': 'Yi wata tambaya',
  'faq.topicAuctions': 'Gwanjo da yanayi',
  'faq.topicPricing': 'Farashi da biya',
  'faq.topicShipping': 'Jigila da takardu',
  'faq.topicArrival': 'Kwastam da isowa',
  'faq.q1': 'Yaya gwanjon motocin Japan ke aiki?',
  'faq.a1': 'Mambobin kasuwanci masu lasisi na binciken motoci da yin tayi a gidajen gwanjo na jumla a fadin Japan. AR7 na zabar lot din da suka dace, ya fassara bayanan mai bincike kuma ya sanya iyakar tayinka da aka amince a madadinka.',
  'faq.q2': 'Zan iya ganin takardar gwanjo kafin tayi?',
  'faq.a2': 'Ga lot din gwanjo, eh — muna raba takardar gwanjo ta Japan da takaitaccen bayani mai sauki na daraja da alamomi kafin ka kulla tayi. Ga motocin hajojin dila, ana duba yanayi daga rahoton dila da hotunan filin.',
  'faq.q3': 'Menene ma\'anar darajoji irin su 4.5, 4.0 da R?',
  'faq.a3': 'Darajoji S, 5, 4.5 da 4.0 na nuna yanayin gaba daya da matakin tafiya, yayin da lambobin panel kamar A1 (karamin kwarzane), U1 (dan kwabo) da W2 (raurawar fenti) ke nuna kowane bangare. Daraja ta R ko RA na nufin tarihin hadari da aka gyara — muna bayyana hakan sarai kafin ka yanke shawara.',
  'faq.q4': 'Ta yaya hajojin dila suka bambanta da motar gwanjo?',
  'faq.a4': 'Ana sayar da motocin gwanjo a ranar da aka tsara kan farashin guduma da yen na Japan, yayin da motocin hajojin dila tuni suke da farashi a shagunan Japan kuma ana iya ajiye su nan take ba tare da jiran zaman gwanjo ba.',
  'faq.q5': 'Shin AR7 na iya samo wani samfuri na musamman?',
  'faq.a5': 'Eh. Bayar da alama, samfuri, shekarun da kake so, iyakar tafiya, launin da kake so da tashar isa. Muna sa ido kan jerin gwanjo na yau da kullum da hanyoyin dila na Japan har sai motar da ta dace ta bayyana.',
  'faq.q6': 'Me ke cikin farashin fitarwa?',
  'faq.a6': 'Farashin da aka lissafa kiyasin farawa ne na FOB (Free on Board) a Japan. Kwatancen rubutu naka na fayyace farashin mota, sufurin cikin Japan da shirye-shiryen fitarwa, kudin jigilar teku da inshorar tafiya ta teku (CIF).',
  'faq.q7': 'Menene bambanci tsakanin farashin FOB da CIF?',
  'faq.a7': 'FOB ya hada mota da shirin fitarwa har zuwa lodi a tashar Japan. CIF (Kudi, Inshora da Jigila) na kara kudin teku zuwa tasharka da inshorar tafiya, don ka ga kudin isa tasha kafin kwastam.',
  'faq.q8': 'Yaya zan biya kuma wadanne kudade ake karba?',
  'faq.a8': 'Ana biyan saye ta hanyar canja wurin banki na kasashen waje (T/T) bisa ankara ta proforma da aka fayyace, yawanci da USD ko JPY. Don tayin gwanjo, ajiya mai dawowa na kunna iyakar tayinka kuma ana tura sauran bayan saye ya yi nasara.',
  'faq.q9': 'Shin lambobin na\'urorin lissafi na shafin kwatance ne na karshe?',
  'faq.a9': 'A\'a — duk sakamakon na\'urorin lissafi da lokutan jigila na shafin kiyasin shiri ne. Kafin ka kulla, teburin fitarwarmu na Japan na fitar da kwatancen rubutu da kudin jigila na yanzu da na takardu don motarka ta musamman.',
  'faq.q10': 'Jigila na daukar tsawon wane lokaci?',
  'faq.a10': 'Tafiyar teku ta dogara ne da tasharka, jadawalin kamfanin jigila da ko jirgi na tafiya kai tsaye ko yana sauya jirgi. Lokutan shiri na yau da kullum sun kama daga kusan kwana 18 zuwa 42 bayan lodi a Japan.',
  'faq.q11': 'In zabi RoRo ko jigilar kwantena?',
  'faq.a11': 'RoRo (Roll-on/Roll-off) shi ne zabin da aka saba kuma mai sauki ga motocin da ke tafiya, SUV da van. Kwantena na kebe ko na tarayya sun dace da supercar masu tsada, motoci masu kasa-kasa ko odar motoci da yawa na dila.',
  'faq.q12': 'Wadanne takardun fitarwa zan samu?',
  'faq.a12': 'Ana shirya kowace jigila da Ankara ta Kasuwanci, Bill of Lading na asali, Takardar Fitarwa ta Japan (takardar soke rajista) da takardar inshorar teku, da kuma takardun binciken kafin jigila (kamar QISJ, JEVIC ko EAA) inda kasuwarka ta bukata.',
  'faq.q13': 'Yaya zan bibiyi motata?',
  'faq.a13': 'Abokan ciniki na samun sabbin bayanai ta dandali da WhatsApp: hotunan isowa filin a Japan, binciken kafin fitarwa, tanadin jirgi, aika Bill of Lading ta courier da kiyasin isowa tasha.',
  'faq.q14': 'Wa ke lissafin harajin shigo kuma wa ke fitar da mota a tashata?',
  'faq.a14': 'Harajin shigo, harajin cikin gida da kudin rajista kullum hukumar kwastam ta kasarka ce ke tantance su bisa dokokin cikin gida. Wakilinka mai lasisi a tashar isa na gabatar da takardun asali da muke aiko maka ya kuma tabbatar da ainihin harajin da za a biya.',

