  'dest.pickKicker': 'MAI NEMAN HANYA',
  'dest.pickH2': 'Ina za mu aika?',
  'dest.openGuide': 'Buɗe jagorar {m}',
  'dest.hubNoteTitle': 'Kwastam da harajin shigo da kaya:',
  'dest.hubNoteBody': 'harajin shigo da kaya, harajin cikin gida da kuɗin rajista koyaushe hukumar kwastam ta ƙasarka ce ke ƙayyade su a tashar shiga — muna shirya cikakken fakitin takardun fitarwa da wakilinka na kwastam ke buƙata, kuma ba ma taɓa faɗin ƙimar haraji.',
  'dest.transit': 'Kiyasin tafiya (adadin tsari):',
  'dest.popular': 'SHAHARARRU:',
  'hb.s1t': 'Gaya mana motar',
  'hb.s1p': 'Aiko da iri, samfuri, shekara, kasafin kuɗi da tashar isa. Za mu zaɓo haja da zaɓuɓɓukan gwanjo masu dacewa.',
  'hb.s1w': 'Tawagarmu ta fitarwa a Japan tana duba jadawalin gwanjo kai tsaye da hajar dillalai bisa ƙa’idojin shekaru da dacewa na ƙasarka kafin aiko maka da gajeriyar jerin.',
  'hb.s2t': 'Karɓi takardu fassararru',
  'hb.s2p': 'Cikakken taƙaitaccen Turanci na kowace takardar gwanjo, tare da hotunan alamomi da gyare-gyare.',
  'hb.s2w': 'Ga kayan gwanjo, kwararre dake Japan yana fassara rubutun hannu na mai bincike, darajojin panel da alamomin ciki zuwa sauƙaƙan harshe; ga hajar dillali, muna raba bayanan yanayin dillali da jerin hotuna.',
  'hb.s3t': 'Saita iyakar tayi',
  'hb.s3p': 'A amince da tsayayyen iyaka kafin tayi — babu mamaki, babu ƙari.',
  'hb.s3w': 'Kana tabbatar a rubuce da iyakar tayi a JPY ko USD tare da kiyasin rabe-raben kuɗin CIF, kuma muna kulle wannan iyaka kafin kayan ya shiga layin gwanjo.',
  'hb.s4t': 'Muna tayi a madadinka',
  'hb.s4p': 'Wakilanmu suna tayi kai tsaye a USS, TAA, JU, CAA da sauransu; kai kana bibiya a portal.',
  'hb.s4w': 'Tawagarmu ta tayi tana sanya tayi kai tsaye a zaure ko ta na’ura har zuwa iyakarka da aka amince, kuma tana raba sakamakon guduma da zarar an rufe kayan.',
  'hb.s5t': 'Bincike da shiri',
  'hb.s5p': 'Hotunan fili masu zaman kansu, binciken ƙarƙashin mota, kwatanta yanayi da takardar gwanjo ko rahoton dillali, da shirye-shiryen kafin fitarwa.',
  'hb.s5w': 'Da motar ta isa filinmu na fitarwa a Japan, muna ɗaukar hotunan waje, ciki da ƙarƙashinta, muna kammala duk wani bincike na tilas kafin jigila (kamar QISJ, JEVIC ko tsabtace kariyar halittu), sannan muna shirya ta don lodi.',
  'hb.s6t': 'Biya a matakai',
  'hb.s6p': 'Adibas yana kunna tayi; saura yana rabuwa kafin da bayan jigila bisa daftarin ka.',
  'hb.s6w': 'Kana karɓar daftarin proforma daki-daki mai nuna farashin mota, shirin fitarwa, kuɗin jirgi da inshorar ruwa, ana biya ta hanyar canja wurin banki (T/T) kuma ana rubuta kowane biyan kuɗi a portal ɗinka.',
  'hb.s7t': 'Takardun fitarwa',
  'hb.s7p': 'Daftari, takardar shaidar fitarwa, bill of lading, inshora — duk tawagarmu ce ke kula.',
  'hb.s7w': 'Muna kammala soke rajista na Japan (Takardar Fitarwa / Yushutsu Massho), muna fitar da Daftarin Kasuwanci da takardar inshorar ruwa, kuma muna aika Bill of Lading na asali ta DHL.',
  'hb.s8t': 'Bibiya har tasharka',
  'hb.s8p': 'Matakai kai tsaye daga filin Japan zuwa tasharka, da takardu shiryayyu don kwastam a isowa.',
  'hb.s8w': 'Kana bibiyar tashin jirgin ruwa da kiyasin isowa a asusunka, yayin da wakilinka na kwastam na gida ke amfani da fakitin takardun da aka aiko don fitar da kaya a tasharka.',
